"""The startup banner: its image, its five seconds, and its ways out.

Split in two deliberately. The timing and the image file need no display and run
everywhere; the window itself needs Tk and skips where there isn't one. Nothing here
sleeps - a suite that waits five real seconds per case is a suite people stop running,
so the clock is injected.
"""

import os
import struct
import sys

import pytest

from conftest import ROOT

sys.path.insert(0, str(ROOT / "manager"))

import splash  # noqa: E402


class TestTheImage:
    """Generated by tools/make_splash.py from the README banner."""

    def _header(self, path):
        with open(path, "rb") as handle:
            data = handle.read(33)
        assert data[:8] == b"\x89PNG\r\n\x1a\n", "%s is not a PNG" % path
        width, height, depth, colour = struct.unpack(">IIBB", data[16:26])
        return width, height, depth, colour

    def test_the_splash_image_ships(self):
        assert os.path.isfile(splash.image_path()), splash.image_path()

    def test_it_is_the_size_the_window_is_built_for(self):
        width, height, _, _ = self._header(splash.image_path())
        assert (width, height) == (724, 242)

    def test_it_is_a_format_tk_can_read_without_pillow(self):
        """8-bit colour PNG. Tk 8.6 reads these natively; anything exotic would need
        Pillow, which is 10 MB on a 10.7 MB exe for one picture."""
        _, _, depth, colour = self._header(splash.image_path())
        assert depth == 8
        assert colour in (2, 6)                 # RGB or RGBA

    def test_it_matches_the_banner_it_was_made_from(self):
        """Catches a banner replaced with a different shape and the splash not
        regenerated - the one way these two files can drift apart."""
        banner = ROOT / "assets" / "ATCAI_Banner.png"
        if not banner.is_file():
            pytest.skip("the full-size banner is not in this checkout")
        bw, bh, _, _ = self._header(str(banner))
        sw, sh, _, _ = self._header(splash.image_path())
        assert abs((bw / bh) - (sw / sh)) < 0.02, (
            "the splash is %.2f:1 but the banner is %.2f:1 - re-run "
            "tools/make_splash.py" % (sw / sh, bw / bh))

    def test_it_is_much_smaller_than_the_banner(self):
        """The reason for a build step at all: only this goes in the exe."""
        banner = ROOT / "assets" / "ATCAI_Banner.png"
        if not banner.is_file():
            pytest.skip("the full-size banner is not in this checkout")
        assert os.path.getsize(splash.image_path()) < banner.stat().st_size / 2

    def test_the_manager_does_not_depend_on_pillow(self):
        for name in sorted(os.listdir(ROOT / "manager")):
            if not name.endswith(".py"):
                continue
            text = (ROOT / "manager" / name).read_text(encoding="utf-8")
            assert "PIL" not in text and "Pillow" not in text, name


class TestTheFiveSeconds:
    """"At least five seconds" cuts both ways."""

    def test_a_fast_start_is_held_to_the_full_five(self):
        assert splash.remaining_ms(0) == 5000
        assert splash.remaining_ms(1200) == 3800

    def test_a_slow_start_is_never_cut_short_to_meet_it(self):
        """Seven seconds of startup shows the banner for seven, not five - and crucially
        not five *plus* seven, which is what adding a fixed delay would do."""
        assert splash.remaining_ms(7000) == 0

    def test_it_never_asks_tk_to_wait_a_negative_time(self):
        assert splash.remaining_ms(999999) == 0

    def test_it_measures_from_when_the_splash_went_up(self):
        clock = iter([100.0, 102.5])
        banner = splash.Splash(None, path="/nonexistent",
                               clock=lambda: next(clock))
        banner.show()                                   # records the start
        assert banner.remaining_ms() == 2500


class TestItNeverStopsTheAppOpening:
    """A splash that can prevent startup is worse than no splash."""

    def test_a_missing_image_is_not_fatal(self, tmp_path):
        said = []
        banner = splash.Splash(None, path=str(tmp_path / "gone.png"),
                               on_log=said.append)
        assert banner.show() is False
        assert said, "it should say why there was no splash"

    def test_an_undecodable_image_is_not_fatal(self, tmp_path):
        bad = tmp_path / "bad.png"
        bad.write_bytes(b"\x89PNG\r\n\x1a\n" + b"rubbish")
        said = []
        banner = splash.Splash(None, path=str(bad), on_log=said.append)
        assert banner.show() is False
        assert said

    def test_dismissing_one_that_never_showed_is_harmless(self, tmp_path):
        banner = splash.Splash(None, path=str(tmp_path / "gone.png"))
        banner.show()
        banner.dismiss()
        banner.dismiss()
        assert banner.dismissed


# Only the window tests below need Tk. Skipping is done per-fixture rather than at
# module level, because an importorskip up here would also skip the image and timing
# tests - which need no display and are the half that runs in CI on Linux.
gui = pytest.mark.gui


@pytest.fixture
def tk_root():
    tkinter = pytest.importorskip("tkinter",
                                  reason="tkinter is not available in this Python")
    try:
        root = tkinter.Tk()
    except Exception as exc:                            # no display
        pytest.skip("no display available (%s)" % exc)
    root.withdraw()
    yield root
    root.destroy()


@gui
class TestTheWindow:
    @pytest.fixture
    def banner(self, tk_root):
        shown = splash.Splash(tk_root)
        assert shown.show() is True, "the real image should load"
        yield shown
        shown.dismiss()

    def test_it_is_exactly_the_size_of_the_image(self, banner):
        banner.window.update_idletasks()
        assert (banner.window.winfo_width(),
                banner.window.winfo_height()) == (724, 242)

    def test_it_has_no_title_bar(self, banner):
        assert banner.window.overrideredirect()

    def test_it_is_centred(self, banner):
        banner.window.update_idletasks()
        window = banner.window
        expected_x = (window.winfo_screenwidth() - 724) // 2
        assert abs(window.winfo_x() - expected_x) <= 1

    def test_a_click_asks_to_dismiss(self, banner):
        asked = []
        banner.on_dismiss = lambda: asked.append(True)
        banner._request_dismiss()
        assert asked == [True]

    def test_without_a_handler_a_click_dismisses_directly(self, banner):
        banner.on_dismiss = None
        banner._request_dismiss()
        assert banner.dismissed

    def test_there_is_a_dismiss_button(self, banner):
        """Clicking anywhere works, but only a button tells you so."""
        import tkinter
        buttons = []

        def walk(widget):
            for child in widget.winfo_children():
                if isinstance(child, tkinter.Button):
                    buttons.append(child)
                walk(child)

        walk(banner.window)
        assert buttons, "no dismiss button on the splash"
        assert any("dismiss" in b.cget("text").lower() for b in buttons)

    def test_dismissing_twice_is_harmless(self, banner):
        """The click and the timer both fire, in whichever order."""
        banner.dismiss()
        banner.dismiss()
        assert banner.dismissed and banner.window is None


class TestCentring:
    """The splash and the main window share this, so the banner is replaced in place
    rather than the Manager jumping to wherever Windows would have put it."""

    class Screen:
        def __init__(self, width, height):
            self.width, self.height = width, height

        def winfo_screenwidth(self):
            return self.width

        def winfo_screenheight(self):
            return self.height

    def test_it_centres(self):
        assert splash.centred_geometry(self.Screen(1920, 1080), 900, 700) == \
            "900x700+510+190"

    def test_the_splash_and_the_manager_share_a_centre(self):
        screen = self.Screen(1920, 1080)
        banner = splash.centred_geometry(screen, 724, 242)
        window = splash.centred_geometry(screen, 900, 700)
        centre = lambda g: (int(g.split("+")[1]) + int(g.split("x")[0]) // 2)
        assert centre(banner) == centre(window)

    def test_a_screen_smaller_than_the_window_does_not_go_negative(self):
        """A negative offset puts the title bar above the top of the screen, and the
        window then cannot be dragged back."""
        assert splash.centred_geometry(self.Screen(800, 600), 900, 700) == "900x700+0+0"

    def test_an_exact_fit_sits_at_the_origin(self):
        assert splash.centred_geometry(self.Screen(900, 700), 900, 700) == "900x700+0+0"
